update productos set nombre = 'Laptop HP 15', specs_corto = 'Ryzen 5 · 8 GB RAM · 512 GB SSD · Windows 11 Home', resumen = 'Una laptop rápida y ligera para estudiar, trabajar y ver series.', descripcion_larga = 'La HP 15 combina un procesador AMD Ryzen 5 con disco de estado sólido de 512 GB, así que enciende en segundos y abre tus programas sin esperas. Su pantalla de 15.6 pulgadas Full HD es cómoda para trabajar con varias ventanas, y trae Windows 11 Home listo para usar.', puntos = '[["Rendimiento diario","Ryzen 5 7520U de 4 núcleos para clases en línea, ofimática y navegación."],["Arranque rápido","SSD de 512 GB: el sistema y tus archivos abren en segundos."],["Pantalla amplia","15.6\" Full HD con bordes delgados para ver más en menos espacio."]]'::jsonb, especificaciones = '[["Procesador","AMD Ryzen 5 7520U"],["Memoria","8 GB LPDDR5"],["Almacenamiento","SSD de 512 GB"],["Pantalla","15.6\" Full HD (1920 × 1080)"],["Gráficos","AMD Radeon integrados"],["Sistema operativo","Windows 11 Home"],["Conectividad","Wi-Fi 6 y Bluetooth"]]'::jsonb, galeria = '["/img/LAP-001.webp","/img/g/LAP-001-1.webp","/img/g/LAP-001-2.webp","/img/g/LAP-001-3.webp","/img/g/LAP-001-4.webp"]'::jsonb, versiones = '[{"t":"Almacenamiento","ops":[["512 GB SSD",0],["1 TB SSD",70]]},{"t":"Memoria RAM","ops":[["8 GB",0],["16 GB",60]]}]'::jsonb, orden = 1 where cod = 'LAP-001';
update productos set nombre = 'Laptop HP Victus 15', specs_corto = 'Gaming · Ryzen 7 · 8 GB RAM · 512 GB SSD', resumen = 'Potencia para jugar y crear, con gráficos dedicados NVIDIA.', descripcion_larga = 'La HP Victus 15 está hecha para jugar: procesador AMD Ryzen 7 con tarjeta gráfica NVIDIA GeForce RTX 3050 y pantalla Full HD de 144 Hz para movimientos fluidos. También rinde en edición de video y diseño, con un sistema de enfriamiento pensado para sesiones largas.', puntos = '[["Gráficos dedicados","NVIDIA GeForce RTX 3050 para juegos actuales y edición."],["Pantalla de 144 Hz","Imagen más fluida en juegos rápidos."],["Ryzen 7","Ocho núcleos para jugar, transmitir y trabajar a la vez."]]'::jsonb, especificaciones = '[["Procesador","AMD Ryzen 7 7445HS"],["Gráficos","NVIDIA GeForce RTX 3050"],["Memoria","8 GB DDR5"],["Almacenamiento","SSD de 512 GB"],["Pantalla","15.6\" Full HD, 144 Hz"],["Sistema operativo","Windows 11 Home"]]'::jsonb, galeria = '["/img/LAP-002.webp","/img/g/LAP-002-1.webp","/img/g/LAP-002-2.webp","/img/g/LAP-002-3.webp","/img/g/LAP-002-4.webp"]'::jsonb, versiones = '[{"t":"Almacenamiento","ops":[["512 GB SSD",0],["1 TB SSD",80]]},{"t":"Memoria RAM","ops":[["8 GB",0],["16 GB",70]]}]'::jsonb, orden = 2 where cod = 'LAP-002';
update productos set nombre = 'Laptop Lenovo Core i3', specs_corto = 'Core i3 · 8 GB RAM · 512 GB SSD · Windows 11', resumen = 'La opción más accesible para estudiar y trabajar todos los días.', descripcion_larga = 'La Lenovo IdeaPad Slim 3 es delgada, liviana y confiable. Su procesador Intel Core i3 y su SSD de 512 GB cubren tareas de oficina, clases y entretenimiento, y su teclado cómodo y pantalla Full HD de 15.6 pulgadas la hacen ideal para jornadas largas.', puntos = '[["Delgada y liviana","Fácil de llevar a clases o a la oficina."],["Intel Core i3","Suficiente para ofimática, navegación y videollamadas."],["Wi-Fi 6","Conexión más estable y rápida a internet."]]'::jsonb, especificaciones = '[["Procesador","Intel Core i3-1315U"],["Memoria","8 GB LPDDR5"],["Almacenamiento","SSD de 512 GB"],["Pantalla","15.6\" Full HD"],["Conectividad","Wi-Fi 6 y Bluetooth"],["Sistema operativo","Windows 11"]]'::jsonb, galeria = '["/img/LAP-003.webp","/img/g/LAP-003-1.webp","/img/g/LAP-003-2.webp","/img/g/LAP-003-3.webp","/img/g/LAP-003-4.webp","/img/g/LAP-003-5.webp"]'::jsonb, versiones = '[{"t":"Color","color":true,"ops":[["Azul",0,"#9fb7cf",null],["Gris",0,"#a7abb1",["/img/g/LAP-004-1.webp","/img/g/LAP-004-2.webp","/img/g/LAP-004-3.webp","/img/g/LAP-004-4.webp","/img/g/LAP-004-5.webp"]]]},{"t":"Almacenamiento","ops":[["512 GB SSD",0],["1 TB SSD",70]]}]'::jsonb, orden = 3 where cod = 'LAP-003';
update productos set nombre = 'Laptop Lenovo Ryzen 5', specs_corto = 'Ryzen 5 · 16 GB RAM · 512 GB SSD · Windows 11 Home', resumen = '16 GB de memoria para trabajar con muchas pestañas y programas.', descripcion_larga = 'Esta IdeaPad Slim 3 lleva un procesador AMD Ryzen 5 con 16 GB de memoria, el doble de lo habitual en su rango de precio. Es ideal si trabajas con muchas pestañas abiertas, hojas de cálculo grandes o programas de diseño básico.', puntos = '[["16 GB de memoria","Más programas abiertos al mismo tiempo sin que se ponga lenta."],["Ryzen 5","Rendimiento equilibrado con buena duración de batería."],["Diseño delgado","Cuerpo liviano con acabado gris."]]'::jsonb, especificaciones = '[["Procesador","AMD Ryzen 5 7520U"],["Memoria","16 GB LPDDR5"],["Almacenamiento","SSD de 512 GB"],["Pantalla","15.6\" Full HD"],["Gráficos","AMD Radeon 610M"],["Sistema operativo","Windows 11 Home"]]'::jsonb, galeria = '["/img/LAP-004.webp","/img/g/LAP-004-1.webp","/img/g/LAP-004-2.webp","/img/g/LAP-004-3.webp","/img/g/LAP-004-4.webp","/img/g/LAP-004-5.webp"]'::jsonb, versiones = '[{"t":"Color","color":true,"ops":[["Gris",0,"#a7abb1",null],["Azul",0,"#9fb7cf",["/img/g/LAP-003-1.webp","/img/g/LAP-003-2.webp","/img/g/LAP-003-3.webp","/img/g/LAP-003-4.webp","/img/g/LAP-003-5.webp"]]]},{"t":"Almacenamiento","ops":[["512 GB SSD",0],["1 TB SSD",70]]}]'::jsonb, orden = 4 where cod = 'LAP-004';
update productos set nombre = 'Laptop Acer Aspire Core i7', specs_corto = 'Core i7 · 16 GB RAM · 512 GB SSD · Windows 11', resumen = 'Core i7 y 16 GB para quien necesita más potencia en su trabajo.', descripcion_larga = 'La Acer Aspire con procesador Intel Core i7 y 16 GB de memoria está pensada para profesionales y estudiantes exigentes: hojas de cálculo pesadas, programación, edición de fotos y multitarea intensa. Su cuerpo metálico le da una sensación sólida.', puntos = '[["Intel Core i7","Para programas exigentes y multitarea intensa."],["16 GB de memoria","Trabaja con muchas aplicaciones a la vez."],["Pantalla Full HD","15.6 pulgadas con buena nitidez para trabajar."]]'::jsonb, especificaciones = '[["Procesador","Intel Core i7"],["Memoria","16 GB"],["Almacenamiento","SSD de 512 GB"],["Pantalla","15.6\" Full HD"],["Sistema operativo","Windows 11"]]'::jsonb, galeria = '["/img/LAP-005.webp","/img/g/LAP-005-1.webp","/img/g/LAP-005-2.webp","/img/g/LAP-005-3.webp","/img/g/LAP-005-4.webp","/img/g/LAP-005-5.webp"]'::jsonb, versiones = '[{"t":"Almacenamiento","ops":[["512 GB SSD",0],["1 TB SSD",70]]},{"t":"Memoria RAM","ops":[["16 GB",0],["32 GB",110]]}]'::jsonb, orden = 5 where cod = 'LAP-005';
update productos set nombre = 'Laptop Acer Nitro V 15', specs_corto = 'Gaming · Core i5 · 16 GB RAM · RTX 6 GB', resumen = 'Nuestra laptop gaming más potente, con RTX de 6 GB.', descripcion_larga = 'La Acer Nitro V 15 está lista para jugar títulos actuales con buena calidad: procesador Intel Core i5 de alto rendimiento, tarjeta NVIDIA GeForce RTX de 6 GB y 16 GB de memoria. Su pantalla Full HD de alta frecuencia y su teclado retroiluminado completan la experiencia.', puntos = '[["RTX de 6 GB","Gráficos NVIDIA para jugar y renderizar."],["16 GB de memoria","Juegos y programas abiertos sin trabas."],["Teclado retroiluminado","Para jugar o trabajar de noche."]]'::jsonb, especificaciones = '[["Procesador","Intel Core i5 serie H"],["Gráficos","NVIDIA GeForce RTX 4050, 6 GB"],["Memoria","16 GB"],["Almacenamiento","SSD de 512 GB"],["Pantalla","15.6\" Full HD, 144 Hz"],["Sistema operativo","Windows 11"]]'::jsonb, galeria = '["/img/LAP-006.webp","/img/g/LAP-006-1.webp","/img/g/LAP-006-2.webp","/img/g/LAP-006-3.webp","/img/g/LAP-006-4.webp","/img/g/LAP-006-5.webp"]'::jsonb, versiones = '[{"t":"Almacenamiento","ops":[["512 GB SSD",0],["1 TB SSD",80]]},{"t":"Memoria RAM","ops":[["16 GB",0],["32 GB",110]]}]'::jsonb, orden = 6 where cod = 'LAP-006';
update productos set nombre = 'Galaxy Tab A9+', specs_corto = 'Tablet Samsung · Wi-Fi', resumen = 'Pantalla de 11" para ver, leer y estudiar donde quieras.', descripcion_larga = 'La Galaxy Tab A9+ tiene una pantalla de 11 pulgadas con 90 Hz que hace todo más fluido, cuatro bocinas para películas y videollamadas, y un cuerpo metálico delgado. Perfecta para clases, lectura y entretenimiento en familia.', puntos = '[["Pantalla de 11\"","Amplia y fluida a 90 Hz."],["Sonido envolvente","Cuatro bocinas con Dolby Atmos."],["Para toda la familia","Modo niños y control parental de Samsung."]]'::jsonb, especificaciones = '[["Pantalla","11\", 90 Hz"],["Procesador","Qualcomm Snapdragon"],["Memoria","4 GB"],["Almacenamiento","64 GB, ampliable con microSD"],["Conectividad","Wi-Fi"],["Sistema operativo","Android"]]'::jsonb, galeria = '["/img/TAB-001.webp","/img/g/TAB-001-1.webp","/img/g/TAB-001-2.webp","/img/g/TAB-001-3.webp","/img/g/TAB-001-4.webp","/img/g/TAB-001-5.webp"]'::jsonb, versiones = '[{"t":"Color","color":true,"ops":[["Grafito",0,"#4b4e55",null],["Plata",0,"#d9d9db",["/img/g/TAB-001-plata-1.webp"]]]},{"t":"Almacenamiento","ops":[["64 GB",0],["128 GB",40]]}]'::jsonb, orden = 7 where cod = 'TAB-001';
update productos set nombre = 'Monitor Xiaomi A24i', specs_corto = '24 pulgadas · Full HD', resumen = 'Monitor IPS de 24" para trabajar o jugar con colores fieles.', descripcion_larga = 'El Xiaomi A24i tiene un panel IPS de 23.8 pulgadas con resolución Full HD y 100 Hz, que se ve bien desde cualquier ángulo. Sus bordes delgados lo hacen ideal para escritorios con dos pantallas, y conecta por HDMI o DisplayPort.', puntos = '[["Panel IPS","Colores consistentes desde cualquier ángulo."],["100 Hz","Movimiento más suave que un monitor común de 60 Hz."],["Bordes delgados","Ideal para usar dos monitores lado a lado."]]'::jsonb, especificaciones = '[["Tamaño","23.8\""],["Resolución","1920 × 1080 (Full HD)"],["Panel","IPS"],["Frecuencia","100 Hz"],["Conexiones","HDMI y DisplayPort 1.4"]]'::jsonb, galeria = '["/img/MON-001.webp"]'::jsonb, versiones = '[{"t":"Tamaño","ops":[["24 pulgadas",0],["27 pulgadas",null,null,null,"MON-002"]]}]'::jsonb, orden = 8 where cod = 'MON-001';
