update productos set nombre = 'Teclado Logitech K120', specs_corto = 'USB · Distribución en español', resumen = 'El teclado de siempre: cómodo, silencioso y resistente.', descripcion_larga = 'El Logitech K120 es un teclado de tamaño completo con teclas silenciosas de perfil bajo, distribución en español y conexión USB: lo conectas y funciona. Resiste derrames accidentales, así que es ideal para casa, oficina o centros de estudio.', puntos = '[["Conectar y usar","USB sin instalar programas."],["Resiste derrames","Diseñado para soportar líquidos derramados."],["Teclas silenciosas","Escribe sin molestar a los demás."]]'::jsonb, especificaciones = '[["Conexión","USB con cable"],["Distribución","Español"],["Tipo","Tamaño completo con teclado numérico"],["Compatibilidad","Windows, Linux y ChromeOS"]]'::jsonb, galeria = '["/img/TEC-001.webp","/img/g/TEC-001-1.webp","/img/g/TEC-001-2.webp","/img/g/TEC-001-3.webp"]'::jsonb, versiones = '[]'::jsonb, orden = 10 where cod = 'TEC-001';
