update productos set nombre = 'Teclado mecánico Logitech G413 SE', specs_corto = 'Gaming · USB', resumen = 'Teclas mecánicas táctiles y cubierta de aluminio.', descripcion_larga = 'El Logitech G413 SE es un teclado mecánico de tamaño completo con interruptores táctiles, retroiluminación blanca y una cubierta superior de aluminio. Cada pulsación se siente precisa, tanto para jugar como para escribir durante horas.', puntos = '[["Switches mecánicos","Respuesta táctil y duradera."],["Aluminio","Cubierta superior metálica resistente."],["Anti-ghosting","Reconoce varias teclas a la vez al jugar."]]'::jsonb, especificaciones = '[["Tipo","Mecánico, tamaño completo"],["Interruptores","Táctiles"],["Iluminación","LED blanca"],["Conexión","USB con cable"],["Rollover","6 teclas con anti-ghosting"]]'::jsonb, galeria = '["/img/TEC-003.webp","/img/g/TEC-003-1.webp","/img/g/TEC-003-2.webp","/img/g/TEC-003-3.webp","/img/g/TEC-003-4.webp"]'::jsonb, versiones = '[]'::jsonb, orden = 12 where cod = 'TEC-003';
