update productos set nombre = 'Cámara web Razer Kiyo X', specs_corto = 'USB · Full HD', resumen = 'Cámara Full HD para clases, reuniones y transmisiones.', descripcion_larga = 'La Razer Kiyo X graba en Full HD con enfoque automático, para que te veas nítido en clases, reuniones o transmisiones. Se monta fácilmente sobre tu monitor o laptop y se conecta por USB.', puntos = '[["Full HD","1080p a 30 fps o 720p a 60 fps."],["Enfoque automático","Siempre nítido aunque te muevas."],["Conectar y usar","USB, sin instalar nada."]]'::jsonb, especificaciones = '[["Resolución","1080p a 30 fps · 720p a 60 fps"],["Enfoque","Automático"],["Conexión","USB"],["Montaje","Clip para monitor o laptop"]]'::jsonb, galeria = '["/img/AUD-002.webp"]'::jsonb, versiones = '[]'::jsonb, orden = 18 where cod = 'AUD-002';
update productos set nombre = 'Epson EcoTank L3250', specs_corto = 'Multifuncional · Wi-Fi · Tanque de tinta', resumen = 'Imprime, escanea y copia por Wi-Fi con tinta de bajo costo.', descripcion_larga = 'La Epson EcoTank L3250 imprime, escanea y copia, y se conecta por Wi-Fi para imprimir desde tu celular. Su sistema de tanques recargables reduce mucho el costo por página frente a los cartuchos.', puntos = '[["3 en 1","Imprime, escanea y copia."],["Wi-Fi","Imprime desde tu celular o laptop."],["Tanques recargables","Tinta de bajo costo por página."]]'::jsonb, especificaciones = '[["Funciones","Impresión, escaneo y copia"],["Conexión","Wi-Fi y USB"],["Resolución","Hasta 5760 × 1440 dpi"],["Sistema de tinta","Tanques recargables EcoTank"],["Tamaño de papel","Hasta A4 / carta"]]'::jsonb, galeria = '["/img/IMP-001.webp","/img/g/IMP-001-1.webp","/img/g/IMP-001-2.webp","/img/g/IMP-001-3.webp","/img/g/IMP-001-4.webp","/img/g/IMP-001-5.webp"]'::jsonb, versiones = '[]'::jsonb, orden = 19 where cod = 'IMP-001';
update productos set nombre = 'Canon G1110', specs_corto = 'Impresora de tanque de tinta', resumen = 'Impresora de tanque sencilla y económica para casa.', descripcion_larga = 'La Canon PIXMA G1110 es una impresora de tanques de tinta recargables, ideal para tareas escolares y documentos del hogar. Imprime muchas páginas a bajo costo y se conecta por USB.', puntos = '[["Bajo costo por página","Tanques de tinta recargables."],["Fácil de usar","Conexión USB directa."],["Compacta","Cabe en cualquier escritorio."]]'::jsonb, especificaciones = '[["Funciones","Impresión"],["Conexión","USB"],["Resolución","Hasta 4800 × 1200 dpi"],["Sistema de tinta","Tanques recargables"]]'::jsonb, galeria = '["/img/IMP-002.webp","/img/g/IMP-002-1.webp","/img/g/IMP-002-2.webp"]'::jsonb, versiones = '[]'::jsonb, orden = 20 where cod = 'IMP-002';
update productos set nombre = 'SSD Kingston NV3 1 TB', specs_corto = 'M.2 NVMe', resumen = 'Hasta 6,000 MB/s: tu computadora arrancará en segundos.', descripcion_larga = 'El Kingston NV3 es un SSD M.2 NVMe PCIe 4.0 que alcanza hasta 6,000 MB/s de lectura. Es la mejora más notable que puedes hacerle a una computadora: el sistema, los juegos y los programas cargan muchísimo más rápido.', puntos = '[["PCIe 4.0 NVMe","Hasta 6,000 MB/s de lectura y 4,000 MB/s de escritura."],["Formato M.2 2280","Compatible con la mayoría de laptops y PC modernas."],["5 años de garantía","Respaldo de Kingston."]]'::jsonb, especificaciones = '[["Interfaz","PCIe 4.0 x4 NVMe"],["Formato","M.2 2280"],["Lectura","Hasta 6,000 MB/s"],["Escritura","Hasta 4,000 MB/s"],["Garantía","5 años"]]'::jsonb, galeria = '["/img/ALM-001.webp","/img/g/ALM-001-1.webp","/img/g/ALM-001-2.webp","/img/g/ALM-001-3.webp"]'::jsonb, versiones = '[{"t":"Capacidad","ops":[["1 TB",0],["500 GB",-70],["2 TB",150]]}]'::jsonb, orden = 21 where cod = 'ALM-001';
update productos set nombre = 'Disco externo ADATA HD650 1 TB', specs_corto = 'USB 3.2', resumen = 'Respalda tus fotos y documentos en un disco resistente.', descripcion_larga = 'El ADATA HD650 es un disco duro externo de 1 TB con carcasa resistente a golpes y conexión USB 3.2 para copiar archivos rápido. Ideal para respaldar fotos, trabajos y documentos importantes.', puntos = '[["1 TB de espacio","Miles de fotos, documentos y videos."],["Resistente","Carcasa con protección contra golpes."],["USB 3.2","Copias rápidas y compatibilidad amplia."]]'::jsonb, especificaciones = '[["Capacidad","1 TB"],["Conexión","USB 3.2 Gen 1"],["Formato","2.5\", portátil"],["Alimentación","Por el mismo cable USB"]]'::jsonb, galeria = '["/img/ALM-002.webp","/img/g/ALM-002-1.webp","/img/g/ALM-002-2.webp","/img/g/ALM-002-3.webp","/img/g/ALM-002-4.webp","/img/g/ALM-002-5.webp"]'::jsonb, versiones = '[{"t":"Color","color":true,"ops":[["Negro",0,"#1d1f24",null],["Rojo",0,"#d9302c",["/img/g/ALM-002-rojo-1.webp"]],["Azul",0,"#2f7fe0",["/img/g/ALM-002-azul-1.webp"]]]},{"t":"Capacidad","ops":[["1 TB",0],["2 TB",45]]}]'::jsonb, orden = 22 where cod = 'ALM-002';
update productos set nombre = 'USB Kingston DataTraveler 64 GB', specs_corto = 'Memoria USB', resumen = 'Memoria USB práctica con tapa y llavero de color.', descripcion_larga = 'La Kingston DataTraveler Exodia es una memoria USB 3.2 con tapa protectora y un aro para llavero cuyo color indica la capacidad. Lleva tus archivos a todas partes.', puntos = '[["USB 3.2","Transfiere archivos rápidamente."],["Tapa protectora","Protege el conector."],["Color por capacidad","Identifica cada memoria de un vistazo."]]'::jsonb, especificaciones = '[["Capacidad","64 GB"],["Conexión","USB 3.2 Gen 1"],["Peso","11 g"],["Garantía","5 años"]]'::jsonb, galeria = '["/img/ALM-003.webp","/img/g/ALM-003-1.webp","/img/g/ALM-003-2.webp","/img/g/ALM-003-3.webp","/img/g/ALM-003-4.webp","/img/g/ALM-003-5.webp"]'::jsonb, versiones = '[{"t":"Capacidad","ops":[["64 GB",0],["128 GB",6,null,["/img/g/ALM-003-128-1.webp"]],["256 GB",18,null,["/img/g/ALM-003-256-1.webp"]]]}]'::jsonb, orden = 23 where cod = 'ALM-003';
update productos set nombre = 'RAM Kingston Fury Beast 8 GB', specs_corto = 'DDR4 · 3200 MHz', resumen = 'Más memoria para que tu PC vaya más fluida.', descripcion_larga = 'La Kingston FURY Beast DDR4 de 3200 MHz es una mejora sencilla para PC de escritorio: más memoria significa más programas abiertos y juegos más estables. Su disipador de perfil bajo se ve bien en cualquier equipo.', puntos = '[["DDR4 a 3200 MHz","Velocidad adecuada para juegos y trabajo."],["Overclock automático","Compatible con Intel XMP y AMD Ryzen."],["Garantía de por vida","Respaldo de Kingston."]]'::jsonb, especificaciones = '[["Tipo","DDR4 DIMM (PC de escritorio)"],["Velocidad","3200 MHz"],["Latencia","CL16"],["Garantía","De por vida"]]'::jsonb, galeria = '["/img/COM-001.webp","/img/g/COM-001-1.webp","/img/g/COM-001-2.webp","/img/g/COM-001-3.webp","/img/g/COM-001-4.webp","/img/g/COM-001-5.webp"]'::jsonb, versiones = '[{"t":"Capacidad","ops":[["8 GB",0],["16 GB",60]]}]'::jsonb, orden = 24 where cod = 'COM-001';
update productos set nombre = 'Router TP-Link Archer AX53', specs_corto = 'Wi-Fi 6 · AX3000', resumen = 'Wi-Fi 6 para toda la casa, con cuatro antenas.', descripcion_larga = 'El TP-Link Archer AX53 usa Wi-Fi 6 (AX3000) para dar internet más rápido y estable a más dispositivos a la vez. Sus cuatro antenas amplían la cobertura y sus puertos Gigabit aprovechan al máximo tu plan de internet.', puntos = '[["Wi-Fi 6 AX3000","Más velocidad con muchos dispositivos conectados."],["4 antenas","Mejor cobertura en toda la casa."],["Puertos Gigabit","1 WAN y 4 LAN para conexiones por cable."]]'::jsonb, especificaciones = '[["Estándar","Wi-Fi 6 (802.11ax), AX3000"],["Bandas","2.4 GHz y 5 GHz"],["Puertos","1 WAN + 4 LAN Gigabit"],["Seguridad","WPA3"]]'::jsonb, galeria = '["/img/RED-001.webp","/img/g/RED-001-1.webp","/img/g/RED-001-2.webp","/img/g/RED-001-3.webp","/img/g/RED-001-5.webp"]'::jsonb, versiones = '[{"t":"Modelo","ops":[["Archer AX53 · Wi-Fi 6",0],["Archer C50 · Wi-Fi 5",null,null,null,"RED-002"]]}]'::jsonb, orden = 25 where cod = 'RED-001';
update productos set nombre = 'Router TP-Link Archer C50', specs_corto = 'AC1200 · Doble banda', resumen = 'Router doble banda económico para casa u oficina pequeña.', descripcion_larga = 'El TP-Link Archer C50 ofrece Wi-Fi doble banda AC1200: usa 5 GHz para videos y videollamadas y 2.4 GHz para mayor alcance. Una opción económica y confiable para hogares y oficinas pequeñas.', puntos = '[["Doble banda","2.4 GHz y 5 GHz."],["AC1200","Hasta 1200 Mbps combinados."],["Fácil de instalar","Configuración desde la app Tether."]]'::jsonb, especificaciones = '[["Estándar","Wi-Fi 5 (802.11ac), AC1200"],["Bandas","2.4 GHz (300 Mbps) y 5 GHz (867 Mbps)"],["Puertos","1 WAN + 4 LAN 10/100"]]'::jsonb, galeria = '["/img/RED-002.webp","/img/g/RED-002-1.webp","/img/g/RED-002-2.webp"]'::jsonb, versiones = '[{"t":"Modelo","ops":[["Archer C50 · Wi-Fi 5",0],["Archer AX53 · Wi-Fi 6",null,null,null,"RED-001"]]}]'::jsonb, orden = 26 where cod = 'RED-002';
update productos set nombre = 'UPS Forza NT-751', specs_corto = '750 VA · 6 salidas', resumen = 'Protege tu computadora de apagones y variaciones de voltaje.', descripcion_larga = 'El UPS Forza NT-751 te da tiempo para guardar tu trabajo y apagar tu equipo cuando se va la luz. Su regulador de voltaje protege tu computadora de subidas y bajadas de tensión, comunes en tormentas.', puntos = '[["750 VA / 375 W","Para una computadora con su monitor."],["6 tomas","Conecta tu equipo y periféricos."],["Regulación de voltaje","Protege contra variaciones eléctricas."]]'::jsonb, especificaciones = '[["Capacidad","750 VA / 375 W"],["Tomas","6 NEMA 5-15R"],["Batería","12 V / 7 Ah"],["Protección","Regulación de voltaje y línea RJ11"]]'::jsonb, galeria = '["/img/ENE-001.webp","/img/g/ENE-001-1.webp","/img/g/ENE-001-2.webp","/img/g/ENE-001-3.webp"]'::jsonb, versiones = '[{"t":"Capacidad","ops":[["750 VA",0],["1000 VA",null,null,null,"ENE-002"]]}]'::jsonb, orden = 27 where cod = 'ENE-001';
update productos set nombre = 'UPS Centra Plus 1000VA', specs_corto = 'Pantalla LCD · 8 salidas', resumen = 'Más respaldo y pantalla LCD para ver el estado de la batería.', descripcion_larga = 'El UPS Centra Plus de 1000 VA ofrece más capacidad para equipos con monitor grande o varios dispositivos. Su pantalla LCD muestra el nivel de batería y la carga conectada.', puntos = '[["1000 VA","Más tiempo de respaldo."],["8 tomas","Para tu computadora, monitor, módem y más."],["Pantalla LCD","Estado de batería y carga a la vista."]]'::jsonb, especificaciones = '[["Capacidad","1000 VA"],["Tomas","8"],["Pantalla","LCD"]]'::jsonb, galeria = '[]'::jsonb, versiones = '[{"t":"Capacidad","ops":[["1000 VA",0],["750 VA",null,null,null,"ENE-001"]]}]'::jsonb, orden = 28 where cod = 'ENE-002';
